import math
import sys
from pathlib import Path

import numpy as np


def nint(x):
    return int(x + 0.5)


def parse(path):
    spec, sections, cur = {}, {}, None
    for line in path.read_text().splitlines():
        s = line.strip()
        if not s or s == "EOF":
            continue
        if s.endswith("_SECTION") or s.split()[0].endswith("_SECTION"):
            cur = s.split()[0]
            sections[cur] = []
        elif ":" in s and cur is None or (":" in s and s.split(":")[0].strip().isupper() and not s[0].isdigit() and not s[0] == "-"):
            k, v = s.split(":", 1)
            spec[k.strip()] = v.strip()
            cur = None
        else:
            sections[cur].extend(s.split())
    return spec, sections


def geo(x):
    deg = int(x)
    return 3.141592 * (deg + 5.0 * (x - deg) / 3.0) / 180.0


def matrix(spec, sec):
    n = int(spec["DIMENSION"])
    t = spec["EDGE_WEIGHT_TYPE"]
    d = np.zeros((n, n), dtype=np.int64)
    if t == "EXPLICIT":
        w = [int(float(v)) for v in sec["EDGE_WEIGHT_SECTION"]]
        f = spec["EDGE_WEIGHT_FORMAT"]
        it = iter(w)
        if f == "FULL_MATRIX":
            for i in range(n):
                for j in range(n):
                    d[i, j] = next(it)
        elif f == "UPPER_ROW":
            for i in range(n):
                for j in range(i + 1, n):
                    d[i, j] = d[j, i] = next(it)
        elif f == "LOWER_DIAG_ROW":
            for i in range(n):
                for j in range(i + 1):
                    d[i, j] = d[j, i] = next(it)
        else:
            raise ValueError(f)
        return d
    vals = sec["NODE_COORD_SECTION"]
    pts = [(float(vals[k + 1]), float(vals[k + 2])) for k in range(0, len(vals), 3)]
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            (xi, yi), (xj, yj) = pts[i], pts[j]
            if t == "EUC_2D":
                d[i, j] = nint(math.hypot(xi - xj, yi - yj))
            elif t == "ATT":
                r = math.sqrt(((xi - xj) ** 2 + (yi - yj) ** 2) / 10.0)
                tt = nint(r)
                d[i, j] = tt + 1 if tt < r else tt
            elif t == "GEO":
                lai, loi, laj, loj = geo(xi), geo(yi), geo(xj), geo(yj)
                q1 = math.cos(loi - loj)
                q2 = math.cos(lai - laj)
                q3 = math.cos(lai + laj)
                d[i, j] = int(6378.388 * math.acos(0.5 * ((1 + q1) * q2 - (1 - q1) * q3)) + 1.0)
            else:
                raise ValueError(t)
    return d


def check(d):
    n = len(d)
    off = ~np.eye(n, dtype=bool)
    neg = int((d < 0).sum())
    diag = int((np.diag(d) != 0).sum())
    zero_off = int((d[off] == 0).sum()) // 2
    asym = int((d != d.T).sum()) // 2
    # triangle: d[i,j] <= d[i,k] + d[k,j] for all i,j,k
    via = (d[:, :, None] + d[None, :, :])  # via[i,k,j]
    best = via.min(axis=1)
    viol = d > best
    tri = int(viol.sum())
    worst = 0.0
    if tri:
        excess = (d - best)[viol]
        worst = float(((d - best) / np.maximum(best, 1))[viol].max())
        worst_abs = int(excess.max())
    else:
        worst_abs = 0
    return neg, diag, zero_off, asym, tri, worst_abs, worst


print(f"{'instância':<12}{'tipo':<16}{'neg':>4}{'diag':>5}{'zero':>5}{'asim':>5}{'tri':>6}{'exc.max':>8}{'exc.rel':>9}")
for p in sorted(Path(sys.argv[1]).glob("*.tsp")):
    spec, sec = parse(p)
    d = matrix(spec, sec)
    r = check(d)
    t = spec["EDGE_WEIGHT_TYPE"] + ("/" + spec.get("EDGE_WEIGHT_FORMAT", "") if spec["EDGE_WEIGHT_TYPE"] == "EXPLICIT" else "")
    print(f"{p.stem:<12}{t[:15]:<16}{r[0]:>4}{r[1]:>5}{r[2]:>5}{r[3]:>5}{r[4]:>6}{r[5]:>8}{r[6]:>9.2%}")

