        if not texto or texto == "EOF":
            continue
        primeiro = texto.split()[0]
        if primeiro.endswith("_SECTION"):
            atual = secoes.setdefault(primeiro, [])
        elif campo := _CAMPO.match(texto):
            especificacao[campo.group(1)] = campo.group(2).strip()
