def _matriz_explicita(valores: list[str], n: int, formato: str) -> MatrizCustos:
    pesos: Iterator[int] = (int(float(v)) for v in valores)
    custos = np.zeros((n, n), dtype=np.int64)
    if formato == "FULL_MATRIX":
