        "UPPER_ROW": lambda i: range(i + 1, n),
        "UPPER_DIAG_ROW": lambda i: range(i, n),
        "LOWER_ROW": lambda i: range(i),
        "LOWER_DIAG_ROW": lambda i: range(i + 1),
    }
